theorem related_preserves_invariants {P Q : ResidualPair K}
    (h : Related P Q) :
    moment P = moment Q ∧ delta P = delta Q ∧ deltaStar P = deltaStar Q

theorem trans {X Y Z : WitnessTriple}
    (hXY : FullRelated X Y) (hYZ : FullRelated Y Z) :
    FullRelated X Z

theorem comp {g h : JordanAut} {X Y Z : WitnessTriple}
    (hXY : Transports h X Y) (hYZ : Transports g Y Z) :
    Transports (JordanAut.comp g h) X Z

theorem no_full_transporter_of_traceCubeDetector_ne {X Y : WitnessTriple}
    (h : traceCubeDetector X ≠ traceCubeDetector Y) :
    ¬ ∃ g : JordanAut, Transports g X Y

theorem not_fullRelated_of_traceCubeDetector_ne {X Y : WitnessTriple}
    (h : traceCubeDetector X ≠ traceCubeDetector Y) :
    ¬ FullRelated X Y

theorem c_eq_inverse_adjugate {a : Fin 3 → Mat3 K}
    (S : RawSystem a) (i : Fin 3) :
    S.c i = (S.b i)⁻¹ * (a i).adjugate

theorem skew3_mul_skew3 (a b c p q r : K) :
    skew3 a b c * skew3 p q r =
      !![-a * p - b * q, -b * r, a * r;
         -c * q, -a * p - c * r, -a * q;
         c * p, -b * p, -b * q - c * r]

theorem matrixJordan_mem {A B : Mat6 K}
    (hA : IsSelfAdjoint A) (hB : IsSelfAdjoint B) :
    IsSelfAdjoint (matrixJordan A B)

theorem det_one_add_cayley_ne_zero {A : Mat3 K}
    (hplus : Matrix.det (I₃ + A) ≠ 0) :
    Matrix.det (I₃ + cayley A) ≠ 0

theorem one_add_cayley_mul {A : Mat3 K}
    (hplus : Matrix.det (I₃ + A) ≠ 0) :
    (I₃ + cayley A) * (I₃ + A) = (2 : K) • I₃

theorem one_sub_cayley_mul {A : Mat3 K}
    (hplus : Matrix.det (I₃ + A) ≠ 0) :
    (I₃ - cayley A) * (I₃ + A) = (2 : K) • A
